getPSUIAction.scriptCode:
console.log("聚焦此实体");
const ai_kb_graph_entity = data[0].id;
const graph_tree = view.getCtrl("TREE", "treeexpbar2_tree");
const graph = graph_tree.graph;

focusEntity(ai_kb_graph_entity);
function focusEntity(entityId) {
    // 1. 清除所有节点状态（包括高亮）
    graph.setElementState(
        graph.getNodeData().reduce((acc, node) => {
            acc[node.id] = [];
            return acc;
        }, {})
    );

    // 2. 获取1～2跳邻居节点（去重）
    const keepNodeIds = getNeighborNodes(entityId, 2);

    // 3. 获取保留的边（仅保留子图内的边）
    const keepEdgeIds = new Set();
    graph.getEdges().forEach(edge => {
        const sourceId = edge.getSource().id;
        const targetId = edge.getTarget().id;
        if (keepNodeIds.has(sourceId) && keepNodeIds.has(targetId)) {
            keepEdgeIds.add(edge.id);
        }
    });

    // 4. 隐藏非目标节点和边
    graph.getNodes().forEach(node => {
        if (!keepNodeIds.has(node.id)) node.hide();
    });

    graph.getEdges().forEach(edge => {
        if (!keepEdgeIds.has(edge.id)) edge.hide();
    });

    // 5. 高亮中心节点（增强视觉焦点）
    graph_tree.highlightElement(entityId, "node");
    highlightCenterNode(entityId);
}

// 获取指定跳数的邻居节点（含中心节点）
function getNeighborNodes(entityId, depth) {
    const visited = new Set([entityId]);
    const queue = [{ id: entityId, depth: 0 }];

    while (queue.length) {
        const { id, depth } = queue.shift();

        // 跳数已达上限，停止扩展
        if (depth >= depth) continue;

        // 获取当前节点的所有边
        const edges = graph.getEdgesByNode(graph.findById(id));

        // 遍历所有相邻节点
        edges.forEach(edge => {
            const neighborId = edge.getSource().id === id
                ? edge.getTarget().id
                : edge.getSource().id;

            if (!visited.has(neighborId)) {
                visited.add(neighborId);
                queue.push({ id: neighborId, depth: depth + 1 });
            }
        });
    }

    return visited;
}

// 优化中心节点视觉效果
function highlightCenterNode(entityId) {
    const node = graph.findById(entityId);
    if (!node) return;

    // 1. 调整中心节点大小（放大30%）
    const size = node.getSize();
    node.setSize(size.width * 1.3, size.height * 1.3);

    // 2. 添加高亮状态（确保在隐藏操作后可见）
    node.setState('highlight', true);

    // 3. 确保中心节点在视图中心（G6 v3.0+）
    graph.get('group').animate({
        x: node.get('x'),
        y: node.get('y')
    }, 300, 'easeOutQuad');
}

